import{_ as r,o as i,c as a,a2 as l}from"./chunks/framework.CqpfiAoK.js";const Z=JSON.parse('{"title":"Обзор генеалогии Десяти Тысяч Рас","description":"","frontmatter":{},"headers":[],"relativePath":"ru/50-万族谱系总览.md","filePath":"ru/50-万族谱系总览.md","lastUpdated":null}'),n={name:"ru/50-万族谱系总览.md"};function o(e,t,d,s,h,g){return i(),a("div",null,[...t[0]||(t[0]=[l('<h1 id="обзор-генеалогии-десяти-тысяч-рас" tabindex="-1">Обзор генеалогии Десяти Тысяч Рас <a class="header-anchor" href="#обзор-генеалогии-десяти-тысяч-рас" aria-label="Permalink to &quot;Обзор генеалогии Десяти Тысяч Рас&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Позиция</th><th>Содержание</th></tr></thead><tbody><tr><td>№ документа</td><td>50</td></tr><tr><td>Модуль</td><td>Расы и формы жизни</td></tr><tr><td>Ключевые слова</td><td>Десять Тысяч Рас, генеалогическая классификация, симбиотические отношения, расовое равенство, разнообразие жизни</td></tr></tbody></table><h2 id="i-определение-понятия-десяти-тысяч-рас" tabindex="-1">I. Определение понятия Десяти Тысяч Рас <a class="header-anchor" href="#i-определение-понятия-десяти-тысяч-рас" aria-label="Permalink to &quot;I. Определение понятия Десяти Тысяч Рас&quot;">​</a></h2><p>В Изначальной Вселенной Ваньлин Хэнмао (Вселенная Хэнъюань) «Десять Тысяч Рас» (Wànzú) не означает буквально десять тысяч рас, а является общим термином для всех форм жизни во вселенной, обладающих способностью восприятия и эволюционным потенциалом. Суть понятия Десяти Тысяч Рас заключается в признании бесконечного разнообразия форм жизни и уникальной ценности каждой формы жизни в системе симбиотической эволюции.</p><p>Симбиотическая Цивилизация Якоря устанавливает основополагающий принцип «Равенства Десяти Тысяч Рас»: все формы жизни, независимо от расового происхождения, физиологической структуры, уровня культивации или степени цивилизованности, равны перед законом и пользуются основными правами, предоставленными Симбиотической Конституцией. Этот принцип является фундаментальным отрицанием логики «сильные поглощают всё, слабые гибнут» хищнической космологии.</p><h2 id="ii-система-классификации-генеалогии-десяти-тысяч-рас" tabindex="-1">II. Система классификации генеалогии Десяти Тысяч Рас <a class="header-anchor" href="#ii-система-классификации-генеалогии-десяти-тысяч-рас" aria-label="Permalink to &quot;II. Система классификации генеалогии Десяти Тысяч Рас&quot;">​</a></h2><p>Согласно сущностным характеристикам форм жизни, Десять Тысяч Рас Вселенной Хэнъюань делятся на пять генеалогий, каждая из которых далее подразделяется на конкретные расы:</p><table tabindex="0"><thead><tr><th>Генеалогия</th><th>Название</th><th>Сущностные характеристики</th><th>Представительные расы</th></tr></thead><tbody><tr><td>Первая генеалогия</td><td>Углеродно-материальные расы</td><td>Жизни, основанные на углеродных элементах, с материальным телом как основной формой существования</td><td>Rén Zú (Человеческая Раса), Shòu Zú (Звериная Раса), Lín Zú (Чешуйчатая Раса), Yǔ Zú (Пернатая Раса), Mù Zú (Древесная Раса)</td></tr><tr><td>Вторая генеалогия</td><td>Энергоконденсированные расы</td><td>Жизни, существующие в основном в конденсированной энергетической форме, с материальным телом как вспомогательным или отсутствующим</td><td>Líng Zú (Духовная Раса), Huǒ Zú (Огненная Раса), Shuǐ Zú (Водная Раса), Fēng Zú (Ветряная Раса), Léi Zú (Громовая Раса)</td></tr><tr><td>Третья генеалогия</td><td>Механически-сконструированные расы</td><td>Жизни с механической конструкцией как телом и ядром сознания как сущностью жизни</td><td>Jī Zú (Машинная Раса), Shù Zú (Числовая Раса), Jīng Zú (Кристальная Раса)</td></tr><tr><td>Четвёртая генеалогия</td><td>Расы сознания-информации</td><td>Жизни, существующие в основном в форме сознания и информации, способные отделяться от материальных носителей</td><td>Mèng Zú (Сновидческая Раса), Yǐng Zú (Теневая Раса), Niàn Zú (Мысленная Раса), Hún Zú (Душевная Раса)</td></tr><tr><td>Пятая генеалогия</td><td>Смешанно-вариантные расы</td><td>Новые формы жизни, возникшие в результате слияния и вариации двух или более генеалогий жизни</td><td>Bàn Shòu Zú (Полузвериная Раса), Yāo Líng Zú (Демон-Духовная Раса), Rén Jī Zú (Человеко-Машинная Раса), Shuānghún Tǐ (Сущность Двойной Души)</td></tr></tbody></table><p>Деление на пять генеалогий не является абсолютно изолированным; с продвижением симбиотической эволюции межгенеалогические слияния и вариации учащаются, и масштаб пятой генеалогии, «Смешанно-вариантных рас», продолжает расширяться.</p><h2 id="iii-знакомство-с-основными-расами" tabindex="-1">III. Знакомство с основными расами <a class="header-anchor" href="#iii-знакомство-с-основными-расами" aria-label="Permalink to &quot;III. Знакомство с основными расами&quot;">​</a></h2><h3 id="i-углеродно-материальные-расы" tabindex="-1">(I) Углеродно-материальные расы <a class="header-anchor" href="#i-углеродно-материальные-расы" aria-label="Permalink to &quot;(I) Углеродно-материальные расы&quot;">​</a></h3><ul><li><strong>Rén Zú (Человеческая Раса)</strong> : одна из наиболее широко распространённых и адаптируемых рас Вселенной Хэнъюань, известная своей сильной способностью к обучению, способностью к социальному сотрудничеству и эволюционным потенциалом. Человеческая раса — одна из рас-основателей Симбиотической Цивилизации Якоря, играющая важную роль в управлении цивилизацией.</li><li><strong>Shòu Zú (Звериная Раса)</strong> : раса с чертами животных форм, обычно превосходящая человеческую расу в физической силе и чувствах; некоторые представители обладают особыми врождёнными способностями. Звериная раса делится на десятки ветвей, включая Волчий Клан, Тигриный Клан, Медвежий Клан и Лисий Клан.</li><li><strong>Lín Zú (Чешуйчатая Раса)</strong> : раса с телами, покрытыми чешуёй, живущая преимущественно в воде или влажной среде; некоторые представители обладают подводным дыханием и способностью управления водой. Lóng Zú (Раса Драконов) — самая могущественная ветвь чешуйчатой расы.</li><li><strong>Yǔ Zú (Пернатая Раса)</strong> : раса с крыльями, известная способностью к полёту, живущая преимущественно в высокогорной или горной среде. Пернатая раса делится на ветви, включая Орлиный Клан, Журавлиный Клан и Бабочковый Клан.</li><li><strong>Mù Zú (Древесная Раса)</strong> : раса, в основном характеризующаяся растительными формами, с долгой жизнью и высокой степенью симбиоза с природной средой; некоторые представители обладают способностью управления растениями и исцеления.</li></ul><h3 id="ii-энергоконденсированные-расы" tabindex="-1">(II) Энергоконденсированные расы <a class="header-anchor" href="#ii-энергоконденсированные-расы" aria-label="Permalink to &quot;(II) Энергоконденсированные расы&quot;">​</a></h3><ul><li><strong>Líng Zú (Духовная Раса)</strong> : жизни, сконденсированные из духовной энергии неба и земли, чьи формы могут меняться с сознанием и которые обладают чрезвычайно сильной способностью манипулирования энергией. Духовная раса — одна из рас с наибольшим талантом к культивации.</li><li><strong>Huǒ Zú (Огненная Раса)</strong> : жизни, сконденсированные из энергии пламени, с чрезвычайно высокой температурой тела, искусные в огненных заклинаниях, живущие преимущественно в вулканах или высокотемпературных регионах.</li><li><strong>Shuǐ Zú (Водная Раса)</strong> : жизни, сконденсированные из сущности воды, с полупрозрачным жидким телом, искусные в водных заклинаниях и исцелении, живущие преимущественно в водных регионах.</li><li><strong>Fēng Zú (Ветряная Раса)</strong> : жизни, сконденсированные из сущности ветра, с телом, лёгким как ветер, искусные в ветряных заклинаниях и скоростном бою.</li><li><strong>Léi Zú (Громовая Раса)</strong> : жизни, сконденсированные из энергии грома и молнии, чьи тела содержат мощные электрические токи, искусные в громовых заклинаниях, с чрезвычайно сильной атакующей мощью.</li></ul><h3 id="iii-механически-сконструированные-расы" tabindex="-1">(III) Механически-сконструированные расы <a class="header-anchor" href="#iii-механически-сконструированные-расы" aria-label="Permalink to &quot;(III) Механически-сконструированные расы&quot;">​</a></h3><ul><li><strong>Jī Zú (Машинная Раса)</strong> : раса с точной механической конструкцией как телом, ядром сознания, расположенным в центре тела, обладающая сильной вычислительной способностью и физической защитой.</li><li><strong>Shù Zú (Числовая Раса)</strong> : раса, чья сущность жизни — числа и код, существующая в информационном пространстве, способная свободно перемещаться в цифровом мире и управлять данными.</li><li><strong>Jīng Zú (Кристальная Раса)</strong> : раса с кристаллической конструкцией как телом; кристаллы могут хранить и преобразовывать энергию, и некоторые представители обладают способностями усиления и преломления энергии.</li></ul><h3 id="iv-расы-сознания-информации" tabindex="-1">(IV) Расы сознания-информации <a class="header-anchor" href="#iv-расы-сознания-информации" aria-label="Permalink to &quot;(IV) Расы сознания-информации&quot;">​</a></h3><ul><li><strong>Mèng Zú (Сновидческая Раса)</strong> : жизни, существующие в снах и пространстве сознания, способные входить в сны других, общающиеся в основном через сознание.</li><li><strong>Yǐng Zú (Теневая Раса)</strong> : жизни, существующие в форме тени, способные прикрепляться к объектам или живым существам, обладающие способностями скрытности и незаметного передвижения.</li><li><strong>Niàn Zú (Мысленная Раса)</strong> : жизни, существующие в форме чистой мысли, способные напрямую влиять на материальный мир мыслью, с чрезвычайно сильной психической мощью.</li></ul><h3 id="v-смешанно-вариантные-расы" tabindex="-1">(V) Смешанно-вариантные расы <a class="header-anchor" href="#v-смешанно-вариантные-расы" aria-label="Permalink to &quot;(V) Смешанно-вариантные расы&quot;">​</a></h3><ul><li><strong>Bàn Shòu Zú (Полузвериная Раса)</strong> : смешанная форма человеческой и звериной рас, обладающая и человеческой мудростью, и звериным телосложением.</li><li><strong>Yāo Líng Zú (Демон-Духовная Раса)</strong> : смешанная форма материальных и энергетических рас, обладающая и материальным телом, и способностью манипулирования энергией.</li><li><strong>Rén Jī Zú (Человеко-Машинная Раса)</strong> : смешанная форма человеческой и машинной рас, с частично механизированным телом, обладающая и биологическими, и механическими преимуществами.</li><li><strong>Shuānghún Tǐ (Сущность Двойной Души)</strong> : особая форма жизни, в которой две независимые души сосуществуют в одном теле; её этические вопросы подробно описаны в <em>58-双魂伦理准则</em>.</li></ul><h2 id="iv-симбиотические-отношения-десяти-тысяч-рас" tabindex="-1">IV. Симбиотические отношения Десяти Тысяч Рас <a class="header-anchor" href="#iv-симбиотические-отношения-десяти-тысяч-рас" aria-label="Permalink to &quot;IV. Симбиотические отношения Десяти Тысяч Рас&quot;">​</a></h2><p>Отношения между Десятью Тысячами Рас в Симбиотической Цивилизации Якоря сосредоточены на «симбиозе», что конкретно проявляется в:</p><ol><li><strong>Экономический симбиоз</strong> : каждая раса использует свои преимущества, берёт на себя разные роли в Механизме Совместного Подряда и образует взаимодополняющую сеть экономического сотрудничества.</li><li><strong>Культурный симбиоз</strong> : культурные традиции каждой расы уважаются и защищаются; культурный обмен и взаимное обогащение способствуют общему процветанию цивилизации.</li><li><strong>Культивационный симбиоз</strong> : системы культивации каждой расы взаимно открыты и взаимно ориентированы; Триста Изначальных Систем Культивации предоставляют равные пути эволюции всем расам.</li><li><strong>Политический симбиоз</strong> : представители Десяти Тысяч Рас пропорционально участвуют в Собрании Якоря, совместно решая важные дела цивилизации и обеспечивая право голоса каждой расы.</li><li><strong>Экологический симбиоз</strong> : каждая раса формирует симбиотические отношения с природной средой; физиологические особенности разных рас помогают поддерживать разнообразие и равновесие экосистемы.</li></ol><h2 id="v-предотвращение-и-разрешение-расовых-конфликтов" tabindex="-1">V. Предотвращение и разрешение расовых конфликтов <a class="header-anchor" href="#v-предотвращение-и-разрешение-расовых-конфликтов" aria-label="Permalink to &quot;V. Предотвращение и разрешение расовых конфликтов&quot;">​</a></h2><p>Хотя Симбиотическая Цивилизация Якоря устанавливает принцип расового равенства, расовые различия и исторические противоречия всё ещё могут вызывать конфликты. Государство создаёт следующие механизмы предотвращения и разрешения расовых конфликтов:</p><ul><li><strong>Министерство расовых дел</strong> : специально отвечает за координацию отношений между Десятью Тысячами Рас, урегулирование расовых споров и содействие расовому обмену.</li><li><strong>Комиссия по расовому примирению</strong> : состоит из представителей всех рас, отвечает за медиацию расовых конфликтов и содействие историческому примирению.</li><li><strong>Антидискриминационный закон</strong> : запрещает дискриминационные действия, основанные на расе, и наказывает расовую дискриминацию в соответствии с законом.</li><li><strong>Программа культурного обмена</strong> : регулярно организует мероприятия культурного обмена между всеми расами для укрепления взаимопонимания и уважения.</li><li><strong>Смешанные жилые зоны</strong> : поощряет смешанное проживание всех рас, разрушает расовую сегрегацию и способствует повседневному общению.</li></ul><h2 id="заключение" tabindex="-1">Заключение <a class="header-anchor" href="#заключение" aria-label="Permalink to &quot;Заключение&quot;">​</a></h2><p>Десять Тысяч Рас — самое драгоценное богатство Вселенной Хэнъюань. Разнообразие форм жизни — не источник разделения, а движущая сила симбиотической эволюции. Устанавливая принцип расового равенства, создавая классификацию из пяти генеалогий, способствуя симбиотическому сотрудничеству всех рас и предотвращая и разрешая расовые конфликты, Симбиотическая Цивилизация Якоря освобождает Десять Тысяч Рас от истории грабежа и войны, совместно двигаясь к новой эпохе симбиотической эволюции.</p><h2 id="связанные-документы" tabindex="-1">Связанные документы <a class="header-anchor" href="#связанные-документы" aria-label="Permalink to &quot;Связанные документы&quot;">​</a></h2><ul><li>51-人族定位与特质 (Позиционирование и черты человеческой расы)</li><li>52-异族分类与共生 (Классификация и симбиоз инородных рас)</li><li>05-万族共进基本纲领 (Основная программа совместного продвижения Десяти Тысяч Рас)</li><li>40-共生宪法总纲 (Симбиотическая Конституция: Общие Принципы)</li></ul>',30)])])}const c=r(n,[["render",o]]);export{Z as __pageData,c as default};
